import{_ as a,o as t,c as n,a0 as i}from"./chunks/framework.DB31oXgM.js";const m=JSON.parse('{"title":"ADR 006: Asynchronous Runtime and Threading Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"adr/006-async-runtime-and-threading.md","filePath":"adr/006-async-runtime-and-threading.md"}'),o={name:"adr/006-async-runtime-and-threading.md"};function r(s,e,c,l,d,u){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-006-asynchronous-runtime-and-threading-architecture" tabindex="-1">ADR 006: Asynchronous Runtime and Threading Architecture <a class="header-anchor" href="#adr-006-asynchronous-runtime-and-threading-architecture" aria-label="Permalink to &quot;ADR 006: Asynchronous Runtime and Threading Architecture&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The game server must concurrently manage:</p><ol><li>High-frequency realtime UDP packet processing (thousands of datagrams per second per session).</li><li>Fixed-timestep 60Hz tick execution and compute-heavy rollback resimulation.</li><li>Database persistence, Redis heartbeat/matchmaking operations, and REST/WebSocket client connections.</li></ol><p>Blocking async worker threads with rollback compute can cause network jitter and missed tick deadlines.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Tokio Multi-Thread Runtime</strong>: Use <code>tokio::runtime::Builder::new_multi_thread()</code> with work-stealing for I/O tasks (UDP intake, TCP/WS framing, DB queries, Redis).</li><li><strong>Actor-per-Room Session Runtime</strong>: Each active match room is spawned as an isolated Tokio task or dedicated worker loop communicating via bounded <code>tokio::sync::mpsc</code> channels with strict backpressure (64 packets max queue).</li><li><strong>Pure CPU Simulation Isolation</strong>: Simulation step and rollback resimulation routines are pure synchronous functions executed directly inside the room task, maintaining strictly zero allocation loops in the hot path.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Network I/O and match simulation are fully decoupled.</li><li>Overrun in one room does not stall packet processing for other rooms.</li><li>High memory locality and predictable cache utilization.</li></ul>',11)])])}const p=a(o,[["render",r]]);export{m as __pageData,p as default};
